function attendanceStatusClass(status){
  const s=String(status||'').toLowerCase();
  if(!s)return 'status-empty';
  if(s==='aanwezig')return 'status-aanwezig';
  if(s.includes('herstellend'))return 'status-herstellend';
  if(s.includes('traint met 1'))return 'status-train1';
  if(s.includes('school/werk'))return 'status-schoolwerk';
  if(s.includes('blessure'))return 'status-blessure';
  if(s.includes('vakantie'))return 'status-vakantie';
  if(s.includes('ziek'))return 'status-ziek';
  if(s.includes('geen bericht'))return 'status-geenbericht';
  if(s.startsWith('afwezig'))return 'status-afwezig';
  return 'status-empty';
}
